-- Abyss ({{ mode }}): its colours in Hyprland. Generated by rice-render.
-- hypr.lua loads it, and `rice mode` would send it on its own (hyprctl
-- eval); Abyss is always dark, so it never changes.

-- the focused window: a thin line lit teal into violet, turning slowly
local lit = {
    colors = { "{{ colors.glow | hypr(aa) }}", "{{ colors.glow2 | hypr(aa) }}" },
    angle  = {{ gradient.angle }},
}
-- the rest: the glass's own faint teal edge
local edge = "{{ colors.line | hypr(26) }}"

hl.config({
    general = {
        col = {
            active_border   = lit,
            inactive_border = edge,
        },
    },

    decoration = {
        inactive_opacity = {{ opacity.inactive }},
        blur = {
            brightness = {{ meta.hypr_blur_brightness }},
            vibrancy   = {{ meta.hypr_blur_vibrancy }},
        },
        -- deep and soft: the water under a window goes darker
        shadow = {
            range          = 24,
            color          = "{{ roles.shadow | hypr(aa) }}",
            color_inactive = "{{ roles.shadow | hypr(77) }}",
        },
    },

    group = {
        col = {
            border_active   = lit,
            border_inactive = edge,
        },
        groupbar = {
            text_color          = "{{ roles.fg | hypr(ff) }}",
            text_color_inactive = "{{ roles.muted | hypr(ff) }}",
            col = {
                active   = "{{ roles.selection | hypr(ee) }}",
                inactive = "{{ roles.surface | hypr(cc) }}",
            },
        },
    },

    -- behind everything, so a workspace slide never shows another colour
    misc = { background_color = "{{ roles.bg | hypr(ff) }}" },
})
